-- Production schema captured read-only by the user on 2026-10-12 (PRAGMA user_version = 0). Structure only, no data.
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, is_admin INTEGER NOT NULL DEFAULT 0, disabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, can_generate_paid INTEGER NOT NULL DEFAULT 0, can_text_generate INTEGER NOT NULL DEFAULT 1, can_image_upscale INTEGER NOT NULL DEFAULT 1, can_image_augment INTEGER NOT NULL DEFAULT 1, can_image_encode_vibe INTEGER NOT NULL DEFAULT 1, green_point_used INTEGER NOT NULL DEFAULT 0, green_point_limit INTEGER NOT NULL DEFAULT 4000, green_point_discount INTEGER NOT NULL DEFAULT 0, red_points INTEGER NOT NULL DEFAULT 3000, red_points_used INTEGER NOT NULL DEFAULT 0, green_points_reserved INTEGER NOT NULL DEFAULT 0, red_points_reserved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE daily_quotas (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, quota_date TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (user_id, quota_date));
CREATE TABLE generation_tasks (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL, prompt TEXT NOT NULL, negative_prompt TEXT NOT NULL DEFAULT '', width INTEGER NOT NULL, height INTEGER NOT NULL, steps INTEGER NOT NULL, scale REAL NOT NULL, sampler TEXT NOT NULL, seed INTEGER NOT NULL, cost INTEGER NOT NULL DEFAULT 1, image_path TEXT, error_message TEXT, request_json TEXT NOT NULL, created_at TEXT NOT NULL, completed_at TEXT, mode TEXT NOT NULL DEFAULT 'free', queue_class TEXT, queue_weight INTEGER, virtual_finish REAL, queued_at TEXT, started_at TEXT, anlas_before INTEGER, anlas_after INTEGER, paid_points_charged INTEGER NOT NULL DEFAULT 0, request_fingerprint TEXT, reserved_points INTEGER NOT NULL DEFAULT 0, batch_id TEXT, batch_index INTEGER, reserved_green_points INTEGER NOT NULL DEFAULT 0, reserved_red_points INTEGER NOT NULL DEFAULT 0, consumed_green_points INTEGER NOT NULL DEFAULT 0, consumed_red_points INTEGER NOT NULL DEFAULT 0, released_green_points INTEGER NOT NULL DEFAULT 0, released_red_points INTEGER NOT NULL DEFAULT 0);
CREATE TABLE admin_config (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE quota_usage (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, quota_date TEXT NOT NULL, mode TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (user_id, quota_date, mode));
CREATE TABLE history_hidden (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, task_id TEXT NOT NULL REFERENCES generation_tasks(id) ON DELETE CASCADE, hidden_at TEXT NOT NULL, PRIMARY KEY (user_id, task_id));
CREATE INDEX idx_history_hidden_task_id ON history_hidden(task_id);
CREATE TABLE request_audit_logs (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, service TEXT NOT NULL, path TEXT NOT NULL, method TEXT NOT NULL, status_code INTEGER, request_json TEXT NOT NULL DEFAULT '', error_message TEXT, created_at TEXT NOT NULL, completed_at TEXT, request_content_type TEXT NOT NULL DEFAULT '', request_body_path TEXT, request_body_bytes INTEGER NOT NULL DEFAULT 0, request_body_sha256 TEXT NOT NULL DEFAULT '');
CREATE INDEX idx_request_audit_logs_user_id ON request_audit_logs(user_id);
CREATE INDEX idx_request_audit_logs_created_at ON request_audit_logs(created_at);
CREATE TABLE webauthn_credentials (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, credential_id TEXT NOT NULL UNIQUE, public_key TEXT NOT NULL, sign_count INTEGER NOT NULL DEFAULT 0, aaguid TEXT NOT NULL DEFAULT '', device_type TEXT NOT NULL DEFAULT '', backed_up INTEGER NOT NULL DEFAULT 0, transports TEXT NOT NULL DEFAULT '', disabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, last_used_at TEXT);
CREATE INDEX idx_webauthn_credentials_user_id ON webauthn_credentials(user_id);
CREATE TABLE webauthn_enrollment_tokens (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX idx_webauthn_enrollment_user_id ON webauthn_enrollment_tokens(user_id);
CREATE TABLE webauthn_challenges (id TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, purpose TEXT NOT NULL, challenge TEXT NOT NULL, enrollment_token_hash TEXT, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX idx_webauthn_challenges_user_id ON webauthn_challenges(user_id);
CREATE INDEX idx_generation_tasks_user_fingerprint ON generation_tasks(user_id, request_fingerprint);
CREATE TABLE generation_submission_tasks (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('single', 'batch')), status TEXT NOT NULL, item_count INTEGER NOT NULL DEFAULT 0, reserved_points INTEGER NOT NULL DEFAULT 0, consumed_points INTEGER NOT NULL DEFAULT 0, released_points INTEGER NOT NULL DEFAULT 0, reserved_green_points INTEGER NOT NULL DEFAULT 0, reserved_red_points INTEGER NOT NULL DEFAULT 0, consumed_green_points INTEGER NOT NULL DEFAULT 0, consumed_red_points INTEGER NOT NULL DEFAULT 0, released_green_points INTEGER NOT NULL DEFAULT 0, released_red_points INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, completed_at TEXT, client_request_id TEXT, request_hash TEXT);
CREATE INDEX idx_generation_submission_tasks_user_created ON generation_submission_tasks(user_id, created_at DESC);
CREATE TABLE schema_migrations (migration_key TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE legacy_quota_snapshots (user_id INTEGER PRIMARY KEY, values_json TEXT NOT NULL, captured_at TEXT NOT NULL);
CREATE UNIQUE INDEX idx_generation_submission_tasks_idempotency ON generation_submission_tasks(user_id, client_request_id) WHERE client_request_id IS NOT NULL;
CREATE TABLE client_feedback_reports (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, description TEXT NOT NULL DEFAULT '', client_context_json TEXT NOT NULL, diagnostics_json TEXT NOT NULL, event_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX idx_client_feedback_reports_user_created ON client_feedback_reports(user_id, created_at DESC);
CREATE INDEX idx_client_feedback_reports_created ON client_feedback_reports(created_at DESC);
